def check(ctx):
    s = ctx.object_pose(OBJ)
    if s is None:
        return None
    p = s["pose"]["position"]
    if "ref" not in ctx.state:
        ctx.state["ref"] = {"x": p["x"], "y": p["y"], "z": p["z"]}
        ctx.state["ref_wall_ns"] = s["wall_ns"]
